  vg = 1,
  Qg = "CS-J277-TOPIC-1.4.2",
  bg = "J277",
  xg = "TOPIC",
  _g = "Identifying and preventing vulnerabilities",
  Ag = { code: "1.4.2", title: "Identifying and preventing vulnerabilities" },
  Cg = null,
